import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // Event key = 2*coordinate + (1 for +1, 0 for -1); the closed interval ends at x+r+1.
        long[] e = new long[2 * n];
        for (int i = 0; i < n; i++) {
            long x = nextLong(), r = nextLong();
            e[2 * i] = (x - r) * 2 + 1;
            e[2 * i + 1] = (x + r + 1) * 2;
        }
        Arrays.sort(e);
        long ans = 0;
        int cov = 0;
        for (int i = 0; i < e.length; ) {
            long p = e[i] >> 1;
            while (i < e.length && (e[i] >> 1) == p) cov += (e[i++] & 1) == 1 ? 1 : -1;
            // Coverage is constant from p up to the next event coordinate.
            if (i < e.length && cov == 1) ans += (e[i] >> 1) - p;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	// Event key = 2*coordinate + (1 for +1, 0 for -1); the closed interval ends at x+r+1.
	e := make([]int, 2*n)
	for i := 0; i < n; i++ {
		x, r := readInt(), readInt()
		e[2*i] = (x-r)*2 + 1
		e[2*i+1] = (x + r + 1) * 2
	}
	sort.Ints(e)
	ans, cov := 0, 0
	for i := 0; i < len(e); {
		p := e[i] >> 1
		for i < len(e) && e[i]>>1 == p {
			if e[i]&1 == 1 {
				cov++
			} else {
				cov--
			}
			i++
		}
		// Coverage is constant from p up to the next event coordinate.
		if i < len(e) && cov == 1 {
			ans += e[i]>>1 - p
		}
	}
	fmt.Println(ans)
}
